<form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>" class="seom-panel"><input type="hidden" name="action" value="seom_save_settings"><?php wp_nonce_field('seom_save_settings'); ?><h2>General SEO</h2><p class="description">Keep site-wide search appearance defaults in one place. Per-page SEO overrides live inside the WordPress editor.</p><div class="seom-form-grid"><label>Default SEO Title Format<input name="title_format" value="<?php echo esc_attr(seom_get('title_format','%%title%% | %%sitename%%')); ?>"><small>Variables: <code>%%title%%</code>, <code>%%sitename%%</code>, <code>%%separator%%</code>.</small></label><label>Default Meta Description<textarea name="default_description" rows="3"><?php echo esc_textarea(seom_get('default_description','')); ?></textarea></label><label>Website Type<select name="site_type"><option value="organization" <?php selected(seom_get('site_type'),'organization'); ?>>Organization</option><option value="person" <?php selected(seom_get('site_type'),'person'); ?>>Person</option></select></label><label>Organization / Person Name<input name="org_name" value="<?php echo esc_attr(seom_get('org_name','')); ?>"></label><label>Logo URL<input type="text" inputmode="url" name="org_logo" value="<?php echo esc_attr(seom_get('org_logo','')); ?>"></label><label>Default Social Image<input type="text" inputmode="url" name="default_social_image" value="<?php echo esc_attr(seom_get('default_social_image','')); ?>"></label><label>Twitter Card<select name="twitter_card"><option value="summary_large_image" <?php selected(seom_get('twitter_card'),'summary_large_image'); ?>>Summary Large Image</option><option value="summary" <?php selected(seom_get('twitter_card'),'summary'); ?>>Summary</option></select></label><label>Default Schema Type<select name="schema_type"><option value="auto" <?php selected(seom_get('schema_type'),'auto'); ?>>Automatic</option><option value="Article" <?php selected(seom_get('schema_type'),'Article'); ?>>Article</option><option value="WebPage" <?php selected(seom_get('schema_type'),'WebPage'); ?>>WebPage</option></select></label><label>404 Log Retention (days)<input type="number" min="1" max="3650" name="404_retention" value="<?php echo (int)seom_get('404_retention',30); ?>"></label><label class="seom-toggle-row inline"><span><strong>Breadcrumb Schema</strong><small>Include a BreadcrumbList block in the JSON-LD output for singular content.</small></span><input type="checkbox" name="breadcrumbs" value="1" <?php checked((int)seom_get('breadcrumbs',1),1); ?>></label></div><p><button class="button button-primary">Save General SEO</button></p></form>